{"command":"python3 <<'PY'
import subprocess, os

def run(args, inp, env=None):
    e=dict(os.environ)
    if env: e.update(env)
    if isinstance(inp, str): inp=inp.encode()
    r=subprocess.run(["./executable"]+args, input=inp, capture_output=True, env=e)
    return r

# Check NO_COLOR, TERM, CLICOLOR etc? Let's brute force: run with tty forced color? Already tty gives color automatically.
# Check if NO_COLOR disables tty color? Need tty test with NO_COLOR.
import pty, select, time
def run_tty(args, inp, env_extra=None):
    master, slave = pty.openpty()
    e=dict(os.environ)
    if env_extra: e.update(env_extra)
    proc=subprocess.Popen(["./executable"]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, close_fds=True, env=e)
    os.close(slave)
    try:
        proc.stdin.write(inp if isinstance(inp, bytes) else inp.encode())
        proc.stdin.close()
    except: pass
    out=b""
    end=time.time()+3
    while time.time()<end:
        r,_,_=select.select([master], [], [], 0.5)
        if r:
            try:
                d=os.read(master, 8192)
                if not d: break
                out+=d
            except: break
        if proc.poll() is not None:
            time.sleep(0.2)
            while True:
                r2,_,_=select.select([master], [], [], 0.2)
                if not r2: break
                try:
                    d=os.read(master, 8192)
                    if not d: break
                    out+=d
                except: break
            break
    os.close(master)
    try: proc.wait(timeout=2)
    except: proc.kill()
    return out, proc.returncode

for env in [None, {"NO_COLOR":"1"}, {"TERM":"dumb"}, {"NO_COLOR":""}, {"CLICOLOR":"0"}]:
    out,code=run_tty([], b'<root><a>hi</a></root>', env_extra=env)
    print(f"env {env} -> {repr(out[:500])}")

# Also test piped with -c but NO_COLOR? Does -c override NO_COLOR? In pipe mode, -c forces color regardless.
for env in [None, {"NO_COLOR":"1"}]:
    r=run(["-c"], b'<root><a>hi</a></root>', env=env)
    print(f"pipe -c env {env} -> {repr(r.stdout[:500])}")

# Check piped without -c but with env FORCE_COLOR? CLICOLOR_FORCE?
for env in [{"CLICOLOR_FORCE":"1"}, {"FORCE_COLOR":"1"}]:
    r=run([], b'<root><a>hi</a></root>', env=env)
    print(f"pipe env {env} -> {repr(r.stdout[:500])}")

