package main

import (
 "encoding/xml"
 "fmt"
 "strings"
)

func main() {
 // Try Strict=false? And Decoder with different settings
 tests := []string{
  `<a><b></a></b>`,
  `<root><a>hi</b></root>`,
 }
 for _, t := range tests {
  d := xml.NewDecoder(strings.NewReader(t))
  d.Strict = false
  for {
   tok, err := d.Token()
   fmt.Printf("strict=false tok %T %v err %v\n", tok, tok, err)
   if err != nil { break }
   if tok == nil { break }
  }
  fmt.Println("---")
  d2 := xml.NewDecoder(strings.NewReader(t))
  d2.Strict = false
  d2.AutoClose = xml.HTMLAutoClose
  for {
   tok, err := d2.Token()
   fmt.Printf("autoclose tok %T %v err %v\n", tok, tok, err)
   if err != nil { break }
   if tok == nil { break }
