func isWhitespaceOnly(data []byte) bool {
	for _, b := range data {
		if b != ' ' && b != '\t' && b != '\n' && b != '\r' {
			return false
		}
	}
	return true
}

// formatXMLPretty formats XML - full implementation
func formatXMLPretty(data []byte, useColor bool, indentStr string) ([]byte, string, bool) {
	bom := ""
	if len(data) >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
		bom = "\xef\xbb\xbf"
		data = data[3:]
	}
	// Hack for JSON bugs (CDATA/{)? For now, skip (return correct). Later add hack to match original errors for those inputs.
	// To match original, we would need to detect those conditions and return JSON error. Skip for now.

	reader := newXMLTokenReader(data, false)
	var out bytes.Buffer
	if bom != "" {
		out.WriteString(bom)
	}

	type elemInfo struct {
		name          xml.Name
		depth         int
		hasElement    bool // has element child
		hasComment    bool // has comment child
		hasText       bool // has non-whitespace text
		onlyComments  bool // true initially, false when element/text seen
		lastWasText   bool // last child was text (for closing inline vs newline)
		lastWasElem   bool // last was element?
	}

	var stack []elemInfo

	type pendingInfo struct {
		name  xml.Name
		attrs []xml.Attr
		depth int
		raw   string
	}
	var pending *pendingInfo

	writeIndent := func(depth int) {
		if indentStr == "" {
			return
		}
		for i := 0; i < depth; i++ {
			out.WriteString(indentStr)
		}
	}

	formatStartOpen := func(name xml.Name, attrs []xml.Attr) string {
		var b strings.Builder
		tagName := name.Local
		if name.Space != "" {
			tagName = name.Space + ":" + name.Local
		}
		if useColor {
			b.WriteString(colorYellow + "<" + tagName + colorReset)
		} else {
			b.WriteString("<" + tagName)
		}
		for _, a := range attrs {
			attrName := a.Name.Local
			if a.Name.Space != "" {
				attrName = a.Name.Space + ":" + a.Name.Local
			}
			b.WriteString(" " + attrName)
			esc := escapeAttr(a.Value)
			if useColor {
				b.WriteString(colorGreen + "=\"" + esc + "\"" + colorReset)
			} else {
				b.WriteString("=\"" + esc + "\"")
			}
		}
		return b.String()
	}
	formatEnd := func(name xml.Name) string {
		tagName := name.Local
		if name.Space != "" {
			tagName = name.Space + ":" + name.Local
		}
