			return []byte("\xef\xbb\xbf\n"), false
		}
	} else {
		if isWhitespaceOnly(data) {
			return []byte("\n"), false
		}
	}
	// If htmlFlag forced, skip JSON detection, go to HTML/text
	if htmlFlag {
		// If contains '<', format as HTML, else text
		if bytes.Contains(data, []byte("<")) {
			out, errMsg, hasErr := formatHTMLPretty(data, useColor, indentStr)
			if hasErr {
				// HTML pretty never errors? Except panics for text? But HTML with '<' should not error (HTML parser lenient). So hasErr false.
				// But just in case, handle like XML.
				if isLast {
					// For inplace, only error, no partial? But HTML never errors, so ignore.
					if isInplace {
						return []byte("Error: " + errMsg + "\n"), true
					}
					return append(out, []byte("Error: "+errMsg+"\n")...), true
				}
				return out, false
			}
			return out, false
		}
		// Text (no '<')
		// formatText may panic (for trailing spaces) - let it panic (will be caught? No, panic propagates, with partial already written? For text, panic has no partial, stdout empty. Our formatText panics before returning, caller hasn't written anything yet. For multi-file incremental, previous files already written. Good. For single file, nothing written yet, stdout empty on panic. Good matches original (stdout empty).
		out := formatText(data)
		return out, false
	}
	// Auto-detect (no -m): check JSON first (if trimmed starts with { or [)
	trimmed := bytes.TrimSpace(data)
	// Need to handle BOM for JSON? BOM + JSON? e.g., BOM + {"a":1}? Does original detect JSON with BOM? Likely yes (trimmed after BOM?). Let's handle: strip BOM for detection.
	trimCheck := trimmed
	if len(trimCheck) >= 3 && trimCheck[0] == 0xEF && trimCheck[1] == 0xBB && trimCheck[2] == 0xBF {
		trimCheck = bytes.TrimSpace(trimCheck[3:])
	}
	if len(trimCheck) > 0 && (trimCheck[0] == '{' || trimCheck[0] == '[') {
