		out, errMsg, hasErr := formatJSONPretty(data, useColor, indentStr)
		if hasErr {
			if isLast {
				if isInplace {
					return []byte("Error: " + errMsg + "\n"), true
				}
				return append(out, []byte("Error: "+errMsg+"\n")...), true
			}
			return out, false
		}
		return out, false
	}
	// Check for '<' for XML/HTML vs text
	if !bytes.Contains(data, []byte("<")) {
		out := formatText(data)
		return out, false
	}
	// Contains '<': detect HTML vs XML
	if detectHTML(data) {
		out, errMsg, hasErr := formatHTMLPretty(data, useColor, indentStr)
		if hasErr {
			if isLast {
				if isInplace {
					return []byte("Error: " + errMsg + "\n"), true
				}
				return append(out, []byte("Error: "+errMsg+"\n")...), true
			}
			return out, false
		}
		return out, false
	}
	// XML
	out, errMsg, hasErr := formatXMLPretty(data, useColor, indentStr)
	if hasErr {
		if isLast {
			if isInplace {
				return []byte("Error: " + errMsg + "\n"), true
			}
			return append(out, []byte("Error: "+errMsg+"\n")...), true
		}
		return out, false
	}
	return out, false
}

func isWhitespaceOnly(data []byte) bool {
	for _, b := range data {
		if b != ' ' && b != '\t' && b != '\n' && b != '\r' {
			return false
		}
	}
	return true
}

// formatXMLPretty formats XML - full implementation
func formatXMLPretty(data []byte, useColor bool, indentStr string) ([]byte, string, bool) {
	bom := ""
	if len(data) >= 3 && data[0] == 0xEF && data[1] == 0xBB && data[2] == 0xBF {
		bom = "\xef\xbb\xbf"
		data = data[3:]
