func findTopLevelMul(s string) int {
	depthBracket := 0
	depthParen := 0
	inSingle := false
	inDouble := false
	for i, ch := range s {
		if inSingle {
			if ch == '\'' {
				inSingle = false
			}
			continue
		}
		if inDouble {
			if ch == '"' {
				inDouble = false
			}
			continue
		}
		if ch == '\'' {
			inSingle = true
		} else if ch == '"' {
			inDouble = true
		} else if ch == '[' {
			depthBracket++
		} else if ch == ']' {
			if depthBracket > 0 {
				depthBracket--
			}
		} else if ch == '(' {
			depthParen++
		} else if ch == ')' {
			if depthParen > 0 {
				depthParen--
			}
		} else if ch == '*' {
			if depthBracket == 0 && depthParen == 0 {
				// Check if wildcard (preceded by / or @) vs multiply
				// Look backwards past spaces to find previous non-space char
				j := i - 1
				for j >= 0 && s[j] == ' ' {
					j--
				}
				if j >= 0 && (s[j] == '/' || s[j] == '@') {
					continue // wildcard, not multiply
				}
				// Check if part of "/*" with spaces? Already handled via backwards past spaces (finds /). Good.
				// Also need to handle " * " as multiply (with spaces) vs "*" alone as wildcard step (e.g., "*" alone as entire query (relative path, all children)? "*" alone starts with *, isExpression returns false (path), so evalExpr won't be called for "*" alone as top-level expression (since it's path). Good. So here, "*" at top-level in evalExpr (for expressions like "2*3", "a * b", etc.) is multiply. Good.
				return i
			}
		}
	}
	return -1
}

func isOuterParens(s string) bool {
	s = strings.TrimSpace(s)
	if len(s) < 2 || s[0] != '(' || s[len(s)-1] != ')' {
		return false
	}
	depth := 0
	inSingle := false
	inDouble := false
	for i, ch := range s {
		if inSingle {
			if ch == '\'' {
				inSingle = false
			}
			continue
		}
		if inDouble {
			if ch == '"' {
				inDouble = false
			}
			continue
		}
		if ch == '\'' {
			inSingle = true
		} else if ch == '"' {
			inDouble = true
		} else if ch == '(' {
			depth++
		} else if ch == ')' {
			depth--
			if depth == 0 && i != len(s)-1 {
				return false
			}
		}
	}
	return depth == 0
}

func evalComparison(leftStr, rightStr, op string, doc *xNode, ctx *xNode, pos, size int) (*xValue, string, bool) {
	leftVal, _, _ := evalExpr(leftStr, doc, ctx, pos, size)
	rightVal, _, _ := evalExpr(rightStr, doc, ctx, pos, size)
	// Handle nodeset vs nodeset, nodeset vs scalar, scalar vs scalar with XPath existential semantics
	// For = and != with nodesets: true if any pair equals (for =) or any pair not equals (for !=)? Actually != with nodesets: true if any pair not equals? Per spec: nodeset != string true if any node != string. Good.
	// For <, >, <=, >= with nodesets: convert each node to number, compare? Actually <, > with nodesets: convert nodesets to numbers? Per spec: if either is nodeset, convert each node in nodeset to number/string? Hmm. Simplify: for <, >, etc., convert both sides to numbers (via xNumberValue for scalars, and for nodesets, use string value of first node? Or any? Actually XPath: nodeset < number true if any node in nodeset (converted to number) < number. Similarly number < nodeset, nodeset < nodeset (any pair). Implement accordingly.
	// Simplify: implement helper to get list of string/number values for each side (for nodesets, list of string values for each node; for scalars, single value).
	switch op {
	case "=", "!=":
		leftStrs, leftIsNodeset := getComparisonStrings(leftVal)
		rightStrs, rightIsNodeset := getComparisonStrings(rightVal)
		// If either is nodeset, existential: for =, true if any pair equals; for !=, true if any pair not equals? Actually per spec: nodeset = string true if any node equals string. nodeset != string true if any node != string. nodeset = nodeset true if any pair equals. nodeset != nodeset true if any pair not equals.
		// For numbers/booleans vs nodesets? Convert nodeset string values to numbers/booleans? Actually comparison with nodeset and number: convert nodeset string values to numbers, compare numerically? Per spec: if one is nodeset and other is number, convert each node in nodeset to number, compare numerically, true if any satisfies. Similarly for boolean? If one is boolean, convert other to boolean, compare? Actually boolean comparison: if either is boolean, convert both to boolean, compare? Hmm. Simplify: for =/!=, if either is boolean, convert both to boolean and compare (since boolean has priority? Per spec: if one is boolean, both converted to boolean). Good. Else if either is number, convert both to numbers? Actually if one is number, both converted to numbers? Per spec: if one is number, both converted to numbers (nodeset string values to numbers). Good. Else (both strings/nodesets with strings), compare as strings.
		// Check for boolean: if leftVal.typ=="boolean" || rightVal.typ=="boolean", convert both to boolean and compare (for =: ==, for !=: !=).
		if leftVal.typ == "boolean" || rightVal.typ == "boolean" {
			lb := xBooleanValue(leftVal)
			rb := xBooleanValue(rightVal)
			if op == "=" {
				return &xValue{typ: "boolean", boolean: lb == rb}, "", false
			}
			return &xValue{typ: "boolean", boolean: lb != rb}, "", false
		}
		// Check for number: if either is number, convert both to numbers? Actually if one is number, both converted to numbers (for nodesets, each node string to number?).
		if leftVal.typ == "number" || rightVal.typ == "number" {
			// Convert to numbers: for nodesets, list of numbers (each node string to number, NaN for invalid?).
			leftNums := getComparisonNumbers(leftVal)
			rightNums := getComparisonNumbers(rightVal)
			if leftIsNodeset || rightIsNodeset {
				// Existential: for =, true if any pair equals (with NaN never equals, even NaN==NaN false? In XPath, NaN != NaN? Actually NaN compared with = always false, with != always true? Hmm. For simplicity, use == for numbers (with NaN handling: NaN==NaN false in Go (since math.NaN()!=math.NaN()). Good. Our NaN placeholder is 0 (not NaN), so wrong. Need proper NaN handling with math.NaN(). For now, use 0 placeholder, ignore NaN edge (rare).
				for _, ln := range leftNums {
					for _, rn := range rightNums {
						if op == "=" {
							if ln == rn {
								return &xValue{typ: "boolean", boolean: true}, "", false
							}
						} else {
							if ln != rn {
								return &xValue{typ: "boolean", boolean: true}, "", false
							}
						}
					}
				}
				if op == "=" {
					return &xValue{typ: "boolean", boolean: false}, "", false
				}
				return &xValue{typ: "boolean", boolean: false}, "", false
			}
			// Both scalars (numbers): direct compare
			if op == "=" {
				return &xValue{typ: "boolean", boolean: leftNums[0] == rightNums[0]}, "", false
			}
			return &xValue{typ: "boolean", boolean: leftNums[0] != rightNums[0]}, "", false
		}
		// Both strings/nodesets (as strings): existential string compare
		for _, ls := range leftStrs {
			for _, rs := range rightStrs {
				if op == "=" {
					if ls == rs {
						return &xValue{typ: "boolean", boolean: true}, "", false
					}
				} else {
					if ls != rs {
						return &xValue{typ: "boolean", boolean: true}, "", false
					}
				}
			}
		}
		if op == "=" {
			return &xValue{typ: "boolean", boolean: false}, "", false
		}
		// For != with empty nodesets? If either nodeset empty, no pairs, return false (since no pair satisfies !=? Actually per spec, nodeset != string with empty nodeset false (since no node to compare). Good. Our loops with empty leftStrs/rightStrs (empty slices) will not find any pair, return false. Good.
		return &xValue{typ: "boolean", boolean: false}, "", false
	case "<", ">", "<=", ">=":
		// Convert both to numbers (for nodesets, each node string to number, existential: true if any pair satisfies)
		leftNums := getComparisonNumbers(leftVal)
		rightNums := getComparisonNumbers(rightVal)
		for _, ln := range leftNums {
			for _, rn := range rightNums {
				var ok bool
				switch op {
				case "<":
					ok = ln < rn
				case ">":
					ok = ln > rn
				case "<=":
					ok = ln <= rn
				case ">=":
					ok = ln >= rn
				}
				if ok {
					return &xValue{typ: "boolean", boolean: true}, "", false
				}
			}
		}
		return &xValue{typ: "boolean", boolean: false}, "", false
	}
	return &xValue{typ: "boolean", boolean: false}, "", false
}

func getComparisonStrings(v *xValue) ([]string, bool) {
	if v.typ == "nodeset" {
		var res []string
		for _, n := range v.nodes {
			res = append(res, xStringValue(n))
		}
		return res, true
	}
	switch v.typ {
	case "string":
		return []string{v.str}, false
	case "number":
		return []string{formatXPathNumber(v.num)}, false
	case "boolean":
		if v.boolean {
			return []string{"true"}, false
		}
		return []string{"false"}, false
	}
	return []string{}, false
}

func getComparisonNumbers(v *xValue) []float64 {
	if v.typ == "nodeset" {
		var res []float64
		for _, n := range v.nodes {
			s := strings.TrimSpace(xStringValue(n))
			f, err := strconv.ParseFloat(s, 64)
			if err != nil {
				// NaN? Use 0 placeholder? Actually NaN. For comparisons with NaN, all false except !=? Hmm. Use 0 for now (will give wrong for NaN cases, but rare).
				continue // Skip NaN? Actually per spec, NaN comparisons always false (except != with NaN? No, NaN != anything true? Hmm. For simplicity, skip NaN (don't include in list, so no pair satisfies, return false for =, <, etc., but for != with NaN, should be true? Actually per spec, NaN != number true? No, NaN compared with = always false, with != always true? Hmm. For nodeset with NaN vs number with !=, should be true (since NaN != number). Our skip would give false (since no pair). Wrong, but rare (numbers from non-numeric strings like "hello" give NaN). For [@id='1'] (string compare, not number, so not here). For [position()<3] (number compare with numbers, no NaN). Good. So NaN rare. Ignore.
				continue
			}
			res = append(res, f)
		}
		return res
	}
	switch v.typ {
	case "number":
		return []float64{v.num}
	case "string":
		f, err := strconv.ParseFloat(strings.TrimSpace(v.str), 64)
		if err != nil {
			return []float64{}
		}
		return []float64{f}
	case "boolean":
		if v.boolean {
			return []float64{1}
		}
		return []float64{0}
	}
	return []float64{}
}

func xNumberValue(v *xValue) float64 {
	switch v.typ {
	case "number":
		return v.num
	case "string":
		f, err := strconv.ParseFloat(strings.TrimSpace(v.str), 64)
		if err != nil {
			return 0 // NaN placeholder
		}
		return f
	case "boolean":
		if v.boolean {
			return 1
		}
		return 0
	case "nodeset":
		if len(v.nodes) == 0 {
			return 0
		}
		s := strings.TrimSpace(xStringValue(v.nodes[0]))
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0
		}
		return f
	}
	return 0
}
