	s = strings.ReplaceAll(s, "\t", "")
	if s == "" {
		return 0, 0, false
	}
	// Cases: "n", "-n", "+n", "2n", "-2n", "n+2", "n-2", "2n+1", "-2n-1", etc., with optional +b/-b part.
	// Find 'n' position
	idx := strings.Index(s, "n")
	if idx < 0 {
		return 0, 0, false
	}
	aStr := s[:idx]
	bStr := ""
	hasB := false
	if idx+1 < len(s) {
		rest := s[idx+1:]
		if rest != "" {
			// Rest should be +b or -b (with b integer, e.g., "+1", "-1", "+ 1"? Already removed spaces, so "+1", "-1")
			if strings.HasPrefix(rest, "+") || strings.HasPrefix(rest, "-") {
				bStr = rest
				hasB = true
			} else {
				return 0, 0, false
			}
		}
	}
	var a int
	if aStr == "" || aStr == "+" {
		a = 1
	} else if aStr == "-" {
		a = -1
	} else {
		var err error
		a, err = parseInt(aStr)
		if err != nil {
			return 0, 0, false
		}
	}
	b := 0
	if hasB {
		var err error
		b, err = parseInt(bStr)
		if err != nil {
			return 0, 0, false
		}
	}
	return a, b, true
}
