import subprocess, os, pty, select, time

def run_tty(bin, args, inp, env_extra=None):
    master, slave = pty.openpty()
    e=dict(os.environ)
    if env_extra:
        for k,v in env_extra.items():
            if v is None:
                e.pop(k, None)
            else:
                e[k]=v
    proc=subprocess.Popen([bin]+args, stdin=subprocess.PIPE, stdout=slave, stderr=slave, close_fds=True, env=e)
    os.close(slave)
    try:
        proc.stdin.write(inp)
        proc.stdin.close()
    except: pass
    out=b""
    end=time.time()+3
    while time.time()<end:
        r,_,_=select.select([master], [], [], 0.5)
        if r:
            try:
                d=os.read(master, 8192)
                if not d: break
                out+=d
            except: break
        if proc.poll() is not None:
            time.sleep(0.2)
            while True:
                r2,_,_=select.select([master], [], [], 0.2)
                if not r2: break
                try:
                    d=os.read(master, 8192)
                    if not d: break
                    out+=d
                except: break
            break
    os.close(master)
    try: proc.wait(timeout=2)
    except: proc.kill()
    return out, proc.returncode

for bin in ["/tmp/newxq", "/tmp/original_bin"]:
    for args, env in [
        ([], None),
        (["--no-color"], None),
        (["-c"], None),
        ([], {"NO_COLOR":"1"}),
        ([], {"TERM":"dumb"}),
        (["-c"], {"NO_COLOR":"1"}),
        (["-c"], {"TERM":"dumb"}),
    ]:
        out, code = run_tty(bin, args, b'<root><a>hi</a></root>', env_extra=env)
        has_color = b'\x1b[' in out
        print(f"{bin} {args} {env} -> has_color:{has_color} code:{code} out:{repr(out[:200])}")
